// Normalize JSearch + SerpAPI results into one clean format
const out = [];

for (const item of $input.all()) {
  const data = item.json;

  if (data.data && Array.isArray(data.data)) {
    for (const job of data.data) {
      out.push({
        json: {
          id: job.job_id || (job.employer_name + '-' + job.job_title).replace(/\s+/g, '-').toLowerCase(),
          title: job.job_title || '',
          company: job.employer_name || '',
          location: job.job_is_remote ? 'Remote' : (job.job_city || job.job_country || 'Unknown'),
          description: (job.job_description || '').slice(0, 4000),
          url: job.job_apply_link || job.job_google_link || '',
          posted: job.job_posted_at_datetime_utc || '',
          source: 'JSearch'
        }
      });
    }
  }

  if (data.jobs_results && Array.isArray(data.jobs_results)) {
    for (const job of data.jobs_results) {
      const applyLink = (job.apply_options && job.apply_options[0] && job.apply_options[0].link) || job.share_link || '';
      out.push({
        json: {
          id: job.job_id || (job.company_name + '-' + job.title).replace(/\s+/g, '-').toLowerCase(),
          title: job.title || '',
          company: job.company_name || '',
          location: job.location || 'Unknown',
          description: (job.description || '').slice(0, 4000),
          url: applyLink,
          posted: (job.detected_extensions && job.detected_extensions.posted_at) || '',
          source: 'SerpAPI'
        }
      });
    }
  }
}

return out;

// Deduplicate against already-seen job IDs
const jobs = $('Merge & Normalize').all();

const CUTOFF_DAYS = 7;
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - CUTOFF_DAYS);

const seenItems = $input.all();
const seenIds = new Set();
for (const s of seenItems) {
  if (!s.json || !s.json.job_id) continue;
  const seenDate = s.json.date_seen ? new Date(s.json.date_seen) : null;
  if (seenDate && seenDate < cutoff) continue;
  seenIds.add(s.json.job_id);
}

const batchSeen = new Set();
const out = [];

for (const item of jobs) {
  const job = item.json;
  if (!job.id || !job.title || !job.url) continue;
  if (seenIds.has(job.id)) continue;
  if (batchSeen.has(job.id)) continue;
  batchSeen.add(job.id);
  out.push({ json: job });
}

return out;

// Cheap rule-based pre-filter (no API cost)
const STACK_TERMS = ['n8n', 'python', 'openai', 'gpt', 'claude', 'anthropic', 'gemini', 'api', 'automation', 'llm', 'rag', 'webhook', 'zapier', 'make.com'];
const HARD_REJECT = ['us citizens only', 'must relocate', 'relocation required', 'on-site only', 'onsite only', 'security clearance', 'us citizenship required', 'must be located in the us', 'hybrid role'];
const CORE_REJECT = ['tensorflow', 'pytorch', 'cuda', 'computer vision', 'deep learning research'];
const SENIOR_FLAGS = ['8+ years', '10+ years', '7+ years', '9+ years', 'phd required', 'phd preferred'];

const out = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = (job.title + ' ' + job.description).toLowerCase();

  if (HARD_REJECT.some(t => text.includes(t))) continue;
  if (CORE_REJECT.some(t => text.includes(t))) continue;

  const isSenior = job.title.toLowerCase().includes('senior') || job.title.toLowerCase().includes('staff') || job.title.toLowerCase().includes('principal');
  if (isSenior && SENIOR_FLAGS.some(t => text.includes(t))) continue;

  if (!STACK_TERMS.some(t => text.includes(t))) continue;

  out.push({ json: job });
}

return out;

// Parse OpenAI's JSON response and attach to the job
const jobs = $('Rule Pre-Filter').all();
const responses = $input.all();
const out = [];

for (let i = 0; i < responses.length; i++) {
  const resp = responses[i].json;
  const job = jobs[i] ? jobs[i].json : null;
  if (!job) continue;

  let scoreData = null;
  try {
    const text = resp.choices[0].message.content;
    scoreData = JSON.parse(text);
  } catch (e) {
    continue;
  }

  out.push({
    json: {
      ...job,
      score: scoreData.score || 0,
      stack_match: scoreData.stack_match || '',
      location_ok: scoreData.location_ok === true,
      experience_fit: scoreData.experience_fit || '',
      blockers: scoreData.blockers || 'none',
      has_red_flags: scoreData.has_red_flags === true,
      red_flags: scoreData.red_flags || '',
      verdict: scoreData.verdict || ''
    }
  });
}

return out;

// Keep only high-relevance jobs, sort, take top 5
const THRESHOLD = 50;

let jobs = $input.all()
  .map(i => i.json)
  .filter(j =>
    j.score >= THRESHOLD &&
    j.location_ok === true &&
    j.has_red_flags !== true
  );

jobs.sort((a, b) => b.score - a.score);
jobs = jobs.slice(0, 5);

return jobs.map(j => ({ json: j }));

// Build the HTML email body from top jobs
const jobs = $input.all().map(i => i.json);

if (jobs.length === 0) {
  return [{ json: { skip: true, html: '', count: 0, topScore: 0 } }];
}

const topScore = jobs[0].score;

let cards = '';
for (const j of jobs) {
  const blockerLine = (j.blockers && j.blockers.toLowerCase() !== 'none')
    ? `<p style="margin:6px 0;color:#b45309;font-size:13px;"><b>Note:</b> ${j.blockers}</p>` : '';
  cards += `
  <div style="border:1px solid #e2e8f0;border-radius:12px;padding:18px;margin-bottom:16px;font-family:Arial,sans-serif;">
    <div style="display:flex;justify-content:space-between;align-items:center;">
      <h3 style="margin:0;color:#0f172a;font-size:18px;">${j.title}</h3>
      <span style="background:#0EA5A0;color:#fff;padding:4px 12px;border-radius:20px;font-size:14px;font-weight:bold;">${j.score}/100</span>
    </div>
    <p style="margin:6px 0;color:#475569;font-size:14px;"><b>${j.company}</b> &middot; ${j.location} &middot; <span style="color:#94a3b8;">${j.source}</span></p>
    <p style="margin:10px 0;color:#334155;font-size:14px;line-height:1.5;">${j.verdict}</p>
    <p style="margin:6px 0;color:#64748b;font-size:13px;">✅ ${j.stack_match}</p>
    <p style="margin:6px 0;color:#64748b;font-size:13px;">📊 ${j.experience_fit}</p>
    ${blockerLine}
    <a href="${j.url}" style="display:inline-block;margin-top:10px;background:#7C3AED;color:#fff;text-decoration:none;padding:10px 22px;border-radius:8px;font-size:14px;font-weight:bold;">Apply Now →</a>
  </div>`;
}

const html = `
<div style="max-width:640px;margin:0 auto;background:#f8fafc;padding:24px;">
  <h2 style="color:#0f172a;font-family:Arial,sans-serif;">🎯 ${jobs.length} New AI Jobs Matched For You</h2>
  <p style="color:#64748b;font-family:Arial,sans-serif;font-size:14px;">Top match score: ${topScore}/100 &middot; Filtered for remote, any-nationality, stack-matched roles only.</p>
  ${cards}
  <p style="color:#94a3b8;font-family:Arial,sans-serif;font-size:12px;text-align:center;margin-top:20px;">Auto-generated by your Smart Job Finder &middot; runs every 6 hours</p>
</div>`;

return [{ json: { skip: false, html, count: jobs.length, topScore } }];

// Build rows of job IDs to save as 'seen'
const jobs = $('Threshold + Top 5').all().map(i => i.json);
const today = new Date().toISOString().slice(0, 10);
return jobs.map(j => ({ json: { job_id: j.id, date_seen: today } }));

const item = $input.first();
const body = item.json;

const statusCode = body.statusCode || body.status || null;
if (statusCode && Number(statusCode) >= 400) {
  throw new Error(`JSearch API failed: HTTP ${statusCode} - ${JSON.stringify(body).slice(0, 300)}`);
}

if (!Array.isArray(body.data) && typeof body.message === 'string') {
  throw new Error(`JSearch API failed: ${body.message}`);
}

return $input.all();

const item = $input.first();
const body = item.json;

const statusCode = body.statusCode || body.status || null;
if (statusCode && Number(statusCode) >= 400) {
  throw new Error(`SerpAPI failed: HTTP ${statusCode} - ${JSON.stringify(body).slice(0, 300)}`);
}

if (typeof body.error === 'string') {
  throw new Error(`SerpAPI failed: ${body.error}`);
}

return $input.all();
